import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-register',
  templateUrl: './register.component.html'
})
export class RegisterComponent {
  regForm: FormGroup;
  loading = false;
  errorMsg = '';
  successMsg = '';
  processInstanceId = '';

  departments = ['Engineering', 'Finance', 'HR', 'Marketing', 'Operations', 'Sales', 'IT', 'Legal'];

  constructor(private fb: FormBuilder, private auth: AuthService, private router: Router) {
    this.regForm = this.fb.group({
      firstName:   ['', Validators.required],
      lastName:    ['', Validators.required],
      email:       ['', [Validators.required, Validators.email]],
      password:    ['', [Validators.required, Validators.minLength(6)]],
      phone:       [''],
      department:  ['', Validators.required],
      designation: ['', Validators.required],
      role:        ['EMPLOYEE']
    });
  }

  onSubmit() {
    if (this.regForm.invalid) return;
    this.loading = true;
    this.errorMsg = '';
    this.successMsg = '';

    this.auth.register(this.regForm.value).subscribe({
      next: res => {
        this.loading = false;
        if (res.success) {
          this.processInstanceId = res.data?.processInstanceId ?? '';
          this.successMsg = res.message;
        } else {
          this.errorMsg = res.message;
        }
      },
      error: err => {
        this.loading = false;
        this.errorMsg = err.error?.message || 'Registration failed. Please try again.';
      }
    });
  }

  get f() { return this.regForm.controls; }
}
<div class="auth-wrapper">
  <div class="auth-card auth-card-wide">
    <div class="auth-header">
      <div class="auth-logo">📋</div>
      <h1>Request Access</h1>
      <p>Fill in your details to register as an employee</p>
    </div>

    <!-- Success state -->
    <div *ngIf="successMsg" class="success-panel">
      <div class="success-icon">✅</div>
      <h3>Registration Submitted!</h3>
      <p>{{ successMsg }}</p>
      <p class="process-id" *ngIf="processInstanceId">
        Process ID: <code>{{ processInstanceId }}</code>
      </p>
      <p class="info-text">HR will review your application. You'll receive an email once approved.</p>
      <button class="btn-primary" routerLink="/login">Back to Login</button>
    </div>

    <!-- Form -->
    <form [formGroup]="regForm" (ngSubmit)="onSubmit()" *ngIf="!successMsg">
      <div class="alert alert-error" *ngIf="errorMsg">⚠️ {{ errorMsg }}</div>

      <div class="form-row">
        <div class="form-group">
          <label>First Name *</label>
          <input type="text" formControlName="firstName" class="form-control"
            [class.is-invalid]="f['firstName'].touched && f['firstName'].invalid" placeholder="John"/>
          <div class="invalid-feedback" *ngIf="f['firstName'].touched && f['firstName'].invalid">Required</div>
        </div>
        <div class="form-group">
          <label>Last Name *</label>
          <input type="text" formControlName="lastName" class="form-control"
            [class.is-invalid]="f['lastName'].touched && f['lastName'].invalid" placeholder="Doe"/>
          <div class="invalid-feedback" *ngIf="f['lastName'].touched && f['lastName'].invalid">Required</div>
        </div>
      </div>

      <div class="form-row">
        <div class="form-group">
          <label>Email Address *</label>
          <input type="email" formControlName="email" class="form-control"
            [class.is-invalid]="f['email'].touched && f['email'].invalid" placeholder="john@company.com"/>
          <div class="invalid-feedback" *ngIf="f['email'].touched && f['email'].errors?.['required']">Required</div>
          <div class="invalid-feedback" *ngIf="f['email'].touched && f['email'].errors?.['email']">Invalid email</div>
        </div>
        <div class="form-group">
          <label>Phone</label>
          <input type="tel" formControlName="phone" class="form-control" placeholder="+1-555-0100"/>
        </div>
      </div>

      <div class="form-row">
        <div class="form-group">
          <label>Department *</label>
          <select formControlName="department" class="form-control"
            [class.is-invalid]="f['department'].touched && f['department'].invalid">
            <option value="">-- Select Department --</option>
            <option *ngFor="let d of departments" [value]="d">{{ d }}</option>
          </select>
          <div class="invalid-feedback" *ngIf="f['department'].touched && f['department'].invalid">Required</div>
        </div>
        <div class="form-group">
          <label>Designation *</label>
          <input type="text" formControlName="designation" class="form-control"
            [class.is-invalid]="f['designation'].touched && f['designation'].invalid" placeholder="Software Engineer"/>
          <div class="invalid-feedback" *ngIf="f['designation'].touched && f['designation'].invalid">Required</div>
        </div>
      </div>

      <div class="form-row">
        <div class="form-group">
          <label>Password *</label>
          <input type="password" formControlName="password" class="form-control"
            [class.is-invalid]="f['password'].touched && f['password'].invalid" placeholder="Min 6 characters"/>
          <div class="invalid-feedback" *ngIf="f['password'].touched && f['password'].errors?.['required']">Required</div>
          <div class="invalid-feedback" *ngIf="f['password'].touched && f['password'].errors?.['minlength']">Min 6 chars</div>
        </div>
        <div class="form-group">
          <label>Role</label>
          <select formControlName="role" class="form-control">
            <option value="EMPLOYEE">Employee</option>
            <option value="MANAGER">Manager</option>
            <option value="HR">HR</option>
          </select>
        </div>
      </div>

      <button type="submit" class="btn-primary btn-full" [disabled]="loading || regForm.invalid">
        <span *ngIf="!loading">Submit Registration</span>
        <span *ngIf="loading">Submitting...</span>
      </button>
    </form>

    <div class="auth-footer" *ngIf="!successMsg">
      <p>Already have an account? <a routerLink="/login">Sign in</a></p>
    </div>
  </div>
</div>
